import React, { useRef, useEffect } from "react";
import "../style/global.css";
import { Spotlight } from "./ui/spotlight.js";
import Navbar from "./Navbar.js";
import { TypewriterEffectSmooth } from "./ui/typewriter-effect.js";
import MyPhoto from "../assets/images/kristian.jpg";
import Html from "../assets/images/html.png";
import Css from "../assets/images/css.png";
import JS from "../assets/images/js.png";
import NodeJs from "../assets/images/NodeJs.png";
import Mysql from "../assets/images/MySQL.png";
import Reactjs from "../assets/images/reactJs.png";
import Tailwind from "../assets/images/Tailwind.png";
import Bootstrap from "../assets/images/bootstrap.png";
import Figma from "../assets/images/Figma.png";
import Photoshop from "../assets/images/photoshop.png";
import Chamy from "../assets/images/chamytwins.jpg";
import CLinique from "../assets/images/clinique.JPG";
import ventelaHub from "../assets/images/ventelahub.JPG";
import { BackgroundBeamsWithCollision } from "./ui/background-beams-with-collision.js";
import { StarsBackground } from "./ui/stars-background.js";
import AOS from "aos";
import "aos/dist/aos.css";

const Home = () => {
  const HomeRef = useRef(null);
  const AboutRef = useRef(null);
  const SkillRef = useRef(null);
  const ProjectRef = useRef(null);
  const ContactRef = useRef(null);

  useEffect(() => {
    AOS.init({
      once: false,
    });
  }, []);

  const goto = (param) => {
    if (param === "skills") {
      const skillElement = SkillRef.current;
      if (skillElement) {
        const rect = skillElement.getBoundingClientRect();
        window.scrollTo({
          top: rect.top + window.scrollY,
          left: 0,
          behavior: "smooth",
        });
      }
    } else if (param === "home") {
      window.scrollTo({
        top: HomeRef.current.offsetTop,
        left: 0,
        behavior: "smooth",
      });
    } else if (param === "about") {
      window.scrollTo({
        top: AboutRef.current.offsetTop,
        left: 0,
        behavior: "smooth",
      });
    } else if (param === "project") {
      window.scrollTo({
        top: ProjectRef.current.offsetTop,
        left: 0,
        behavior: "smooth",
      });
    } else {
      window.scrollTo({
        top: ContactRef.current.offsetTop,
        left: 0,
        behavior: "smooth",
      });
    }
  };

  const words = [
    {
      text: "Hi I'm Kristian, a Frontend Web Developer.",
      className: "custom-text-home",
    },
  ];
  return (
    <div className="web-con m-0 p-0">
      <div className="con1 position-relative overflow-hidden" ref={HomeRef}>
        <Navbar goto={goto} />
        <Spotlight
          className="-top-40 left-0 md:left-60 md:-top-20"
          fill="#4b4dff"
        />
        <div className="text-light text-center position-relative start-50 top-50 translate-middle w-[90%] md:w-[70%]">
          <p className="title-1">MY PERSONAL PORTOFOLIO</p>
          <p className="title-2">
            Transforming Ideas into{" "}
            <span className="custom-text-title">Digital Reality</span>
          </p>
          <div className="d-flex justify-content-center">
            <TypewriterEffectSmooth words={words} />
          </div>
        </div>
      </div>
      <div
        className="con2 position-relative m-0 p-0 overflow-hidden"
        ref={AboutRef}
      >
        <div class="row align-items-center m-0 position-relative top-0 start-50 translate-middle-x w-[80%] lg:w-[90%] custom-row-about">
          <div class="c-12 col-lg-4">
            <div
              className="img-con-about overflow-hidden"
              data-aos="fade-right"
              data-aos-duration="800"
            >
              <img
                className="img-custom-profile"
                src={MyPhoto}
                alt="ProfilePhoto"
              ></img>
            </div>
          </div>
          <div
            class="col-12 col-lg-8 custom-col-about text-light"
            data-aos="fade-left"
            data-aos-duration="800"
            data-aos-delay="200"
          >
            <p className="custom-name-about">KRISTIAN</p>
            <p className="custom-role-about">
              Frontend Developer | Website Designer | UI/UX Designer | Fullstack
              Developer
            </p>
            <p className="custom-text1-about">
              I am a freshgraduate with a Bachelor's degree in Computer Science
              from BINUS University. My primary focus is on frontend
              development, where I specialize in using React JS to build
              responsive and user-friendly websites. Through this
              specialization, I have gained the ability to create dynamic and
              engaging interfaces that work seamlessly across a variety of
              devices, ensuring an optimal user experience.
            </p>
            <p className="custom-text2-about">
              Beyond my technical expertise, I have actively engaged in various
              activities that have significantly honed my leadership and
              communication skills. Through these experiences, I have learned to
              work effectively in team environments, lead projects, and
              communicate ideas clearly and persuasively. These skills
              complement my technical abilities, allowing me to contribute
              effectively to any team or project I am a part of.
            </p>
          </div>
        </div>
      </div>
      <div
        className="con3 m-0 p-0 position-relative overflow-hidden"
        ref={SkillRef}
      >
        <p className="custom-title-skills text-light text-center">Skills</p>
        <div class="row position-relative start-50 top-0 translate-middle-x m-0 p-0 w-[80%]">
          <div class="col">
            <div className="custom-card position-relative start-50 top-0 translate-middle-x">
              <img
                src={Html}
                alt="html"
                className="custom-img object-fit-contain p-3"
              ></img>
            </div>
          </div>
          <div class="col">
            <div className="custom-card position-relative start-50 top-0 translate-middle-x">
              <img
                src={Css}
                alt="css"
                className="custom-img object-fit-contain p-3"
              ></img>
            </div>
          </div>
          <div class="col">
            <div className="custom-card position-relative start-50 top-0 translate-middle-x">
              <img
                src={JS}
                alt="js"
                className="custom-img object-fit-contain p-3"
              ></img>
            </div>
          </div>
          <div class="col">
            <div className="custom-card position-relative start-50 top-0 translate-middle-x">
              <img
                src={Mysql}
                alt="mysql"
                className="custom-img object-fit-contain p-3"
              ></img>
            </div>
          </div>
          <div class="col">
            <div className="custom-card position-relative start-50 top-0 translate-middle-x">
              <img
                src={NodeJs}
                alt="nodejs"
                className="custom-img object-fit-contain p-3"
              ></img>
            </div>
          </div>
        </div>

        <div class="row custom-row2-skill position-relative start-50 top-0 translate-middle-x m-0 w-[80%]">
          <div class="col">
            <div className="custom-card position-relative start-50 top-0 translate-middle-x">
              <img
                src={Reactjs}
                alt="reactjs"
                className="custom-img object-fit-contain p-3"
              ></img>
            </div>
          </div>
          <div class="col">
            <div className="custom-card position-relative start-50 top-0 translate-middle-x">
              <img
                src={Bootstrap}
                alt="bootstrap"
                className="custom-img object-fit-contain p-3"
              ></img>
            </div>
          </div>
          <div class="col">
            <div className="custom-card position-relative start-50 top-0 translate-middle-x">
              <img
                src={Tailwind}
                alt="Tailwind"
                className="custom-img object-fit-contain p-3"
              ></img>
            </div>
          </div>
          <div class="col">
            <div className="custom-card position-relative start-50 top-0 translate-middle-x">
              <img
                src={Figma}
                alt="html"
                className="custom-img object-fit-contain p-3"
              ></img>
            </div>
          </div>
          <div class="col">
            <div className="custom-card position-relative start-50 top-0 translate-middle-x">
              <img
                src={Photoshop}
                alt="html"
                className="custom-img object-fit-contain p-3"
              ></img>
            </div>
          </div>
        </div>
        <StarsBackground />
      </div>
      <div
        className="con4 m-0 p-0 position-relative overflow-hidden"
        ref={ProjectRef}
      >
        <p className="custom-title-skills text-light text-center">
          Featured <span className="custom-text-title">Project</span>
        </p>
        <div class="row row-cols-1 row-cols-md-2 row-cols-xl-3 custom-row-porto m-0">
          <div class="col position-relative">
            <div
              className="card card-chamy z-1"
              data-aos="zoom-in"
              data-aos-duration="800"
            >
              <img
                src={Chamy}
                className="card-img-top custom-img-card p-2"
                alt="..."
              />
              <div className="card-body">
                <h5 className="card-title">ChamyTwins Company Profile</h5>
                <p className="card-text">
                  Bringing ChamyTwins' vision to life with an engaging digital
                  experience, born from a passion for chameleons.
                </p>
                <div className="d-flex text-light text-center">
                  <div className="tech pt-1">Javascript</div>
                  <div className="tech pt-1">ReactJs</div>
                  <div className="tech pt-1">Bootstrap</div>
                </div>
                <a
                  href="https://chamytwins.github.io/ChamyTwins-Website/"
                  target="blank_"
                  className="btn custom-btn btn-primary fw-bold"
                >
                  <i class="bi bi-globe"></i> Website
                </a>
              </div>
            </div>
          </div>
          <div class="col position-relative">
            <div
              className="card card-clinique z-1"
              data-aos="zoom-in"
              data-aos-duration="800"
            >
              <img
                src={CLinique}
                className="card-img-top custom-img-card2 p-2"
                alt="..."
              />
              <div className="card-body">
                <h5 className="card-title">Clinique Online Reservation</h5>
                <p className="card-text2">
                  Simplifying clinic appointments with a seamless and convenient
                  online reservation experience, making healthcare more
                  accessible to you.
                </p>
                <div className="d-flex text-light text-center">
                  <div className="tech pt-1">Javascript</div>
                  <div className="tech pt-1">ReactJs</div>
                  <div className="tech pt-1">Bootstrap</div>
                </div>
                <a
                  href="https://clinique1414.github.io/Clinique.github.io/"
                  target="blank_"
                  className="btn custom-btn btn-primary fw-bold"
                >
                  <i class="bi bi-globe"></i> Website
                </a>
              </div>
            </div>
          </div>
          <div class="col custom-col-ventelahub position-relative">
            <div
              className="card card-ventelahub z-1"
              data-aos="zoom-in"
              data-aos-duration="800"
            >
              <img
                src={ventelaHub}
                className="card-img-top custom-img-card2 p-2"
                alt="..."
              />
              <div className="card-body">
                <h5 className="card-title">Ventelahub Online Marketplace</h5>
                <p className="card-text2">
                  Delivering authentic Ventela shoes with an efficient online
                  shopping experience, ensuring quality and convenience.
                </p>
                <div className="d-flex text-light text-center">
                  <div className="tech pt-1">Javascript</div>
                  <div className="tech pt-1">ReactJs</div>
                  <div className="tech pt-1">Bootstrap</div>
                </div>
                <a
                  href="https://ventelahub.com"
                  target="blank_"
                  className="btn custom-btn btn-primary fw-bold"
                >
                  <i class="bi bi-globe"></i> Website
                </a>
              </div>
            </div>
          </div>
        </div>
        <StarsBackground />
      </div>
      <div
        className="con5 m-0 p-0 position-relative overflow-hidden"
        ref={ContactRef}
      >
        <BackgroundBeamsWithCollision>
          <div
            className="custom-con-contact position-relative start-50 top-0 translate-middle-x"
            data-aos="fade-up"
            data-aos-duration="1000"
            data-aos-easing="linear"
          >
            <p className="custom-title-contact text-center">
              It’s Time to Make Your{" "}
              <span className="custom-text-title"> Ideas </span> into a Stunning{" "}
              <span className="custom-text-title">Digital Reality</span> !
            </p>
            <p className="custom-text-contact text-center">
              Get in touch now to find out how I can help you reach your goals.
              I welcome new ideas and opportunities for engaging and significant
              projects.
            </p>
            <a
              className="inline-flex custom-btn-contact h-12 lg:h-14 animate-shimmer items-center justify-center rounded-lg border border-slate-800 bg-[linear-gradient(110deg,#000103,45%,#9e9e76,55%,#000103)] bg-[length:200%_100%] px-6 font-medium text-slate-300 transition-colors focus:outline-none focus:ring-2 focus:ring-slate-300 focus:ring-offset-2 focus:ring-offset-slate-50 position-relative top-0 start-50 translate-middle-x"
              href="mailto:kristian14214@gmail.com"
              target="blank_"
            >
              <i class="bi bi-envelope-arrow-up-fill"></i> &nbsp; Reach Me on
              Email
            </a>
            <div className="d-flex custom-con-copyright w-[90%] position-relative start-50 top-0 translate-middle-x">
              <p className="custom-text-copyright">© Kristian - 2024</p>
              <div className="d-flex position-absolute end-0">
                <div className="sosmed-con-ig position-relative">
                  <a
                    href="https://www.instagram.com/kristian14_?igsh=Z2FsNW5nYjBqa2s4"
                    target="blank_"
                  >
                    <i class="bi bi-instagram position-absolute start-50 top-50 translate-middle custom-size-sosmed "></i>
                  </a>
                </div>
                <div className="sosmed-con-linked position-relative">
                  <a
                    href="https://www.linkedin.com/in/kristian-kristian-08a2191ba/"
                    target="blank_"
                  >
                    <i class="bi bi-linkedin position-absolute start-50 top-50 translate-middle custom-size-sosmed"></i>
                  </a>
                </div>
              </div>
            </div>
          </div>
        </BackgroundBeamsWithCollision>
      </div>
    </div>
  );
};

export default Home;
